def linear_search(values, target):
    checks = 0
    for i, value in enumerate(values):
        checks += 1
        if value == target:
            return i, checks
    return -1, checks


def binary_search(values, target):
    low, high = 0, len(values) - 1
    checks = 0
    while low <= high:
        mid = (low + high) // 2
        checks += 1
        if values[mid] == target:
            return mid, checks
        if values[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1, checks

